use super::*;use crate::original_building_fragments::{View,World};
fn fixture(name:&str)->Option<String>{std::path::Path::new(env!("CARGO_MANIFEST_DIR")).ancestors().find_map(|p|std::fs::read_to_string(p.join(name)).ok().or_else(||std::fs::read_to_string(p.join("work/parity-audit").join(name)).ok()))}
fn hash(b:impl IntoIterator<Item=u8>)->u32{b.into_iter().fold(2166136261,|h,n|(h^u32::from(n)).wrapping_mul(16777619))}fn hex(b:impl IntoIterator<Item=u8>)->String{b.into_iter().map(|n|format!("{n:02x}")).collect()}
struct Env{s:usize,crt:usize,blast:usize,spark:usize,flag:u8,draws:Vec<Record>}
impl World for Env{fn contact_mode(&mut self,v:bool){self.flag=u8::from(v);}fn submit(&mut self,r:Record){self.draws.push(r);}fn environment(&mut self,_:[i16;2]){self.blast+=1;}fn spark(&mut self,_:[i16;2]){self.spark+=1;}fn crt(&mut self)->u16{let r=(self.s*3571+self.crt*131+0x1743)&32767;self.crt+=1;r as u16}}
#[test]fn fort_constructor_uses_per_row_timing_and_scales_negative_two_without_build_exemption(){let mut p=Pool::default();p.records[0].bytes[4]=73;p.records[0].bytes[17]=91;construct(&mut p,[100,200],&[[3,7,-120,-2,4,2],[5,9,140,3,8,6]],90);assert_eq!((p.records[0].word(0),p.records[0].word(2),p.records[0].word(10)),(103,175,-20));assert_eq!((p.records[1].bytes[13],p.records[1].bytes[15],p.records[1].bytes[16]),(8,6,6));assert_eq!((p.records[0].bytes[4],p.records[0].bytes[17]),(73,91));}
#[test]fn optional_96_actual_fort_callbacks_match_all_four_warm_pools_and_every_draw_byte(){let Some(csv)=fixture("v41-fort-fragments-three-ticks.jsonl")else{return;};let mut pools: [Pool;4]=std::array::from_fn(|_|Pool::default());let mut all=2166136261u32;let mix=|h:&mut u32,n:u32|*h=(*h^n).wrapping_mul(16777619);let mut count=0;for line in csv.lines(){let r:crate::Value=serde_json::from_str(line).unwrap();let n=|k:&str|r[k].as_i64().unwrap();let s=n("scenario")as usize;let tick=n("tick");if tick==0{for(p,pool)in pools.iter_mut().enumerate(){for(slot,rec)in pool.records.iter_mut().enumerate(){rec.bytes=std::array::from_fn(|j|(s*19+p*23+slot*13+j*7)as u8);rec.set(0,if slot<[0,1,25,49,50][s%5]{100+slot as i16}else{-1});rec.set(2,200);rec.set(8,120);rec.set(10,9999);rec.bytes[14]=4;}}assert_eq!(hash(pools.iter().flat_map(|p|p.records.iter().flat_map(|r|r.bytes))),n("before")as u32);let templates=r["templates"].as_array().unwrap().iter().map(|r|std::array::from_fn(|i|r[i].as_i64().unwrap()as i16)).collect::<Vec<_>>();for p in 0..2{let current=[0i16,1,9,900,32767,-1,-32768,100][s%8].wrapping_add(p as i16*9);construct(&mut pools[p],[[400i16,-32768,32767,0][s/5%4].wrapping_add(p as i16*32),500+p as i16*32],&templates,current);}assert_eq!(hex(pools.iter().flat_map(|p|p.records.iter().flat_map(|r|r.bytes))),r["constructed"]);}
 let mut env=Env{s,crt:0,blast:0,spark:0,flag:13,draws:Vec::new()};let damage=[0,1,100,32767][s/8%4];for(pool,p)in pools.iter_mut().zip(0..4){assert_eq!(r["args"][p][0],0x595d06+p*900);assert_eq!(r["args"][p][1],damage);pool.advance(damage,View{camera:[0,0],size:[800,600],multiplayer:s&1!=0},&mut env);}let after=hash(pools.iter().flat_map(|p|p.records.iter().flat_map(|r|r.bytes)));assert_eq!(hex(pools.iter().flat_map(|p|p.records.iter().flat_map(|r|r.bytes))),r["after"]);assert_eq!(hex(env.draws.iter().flat_map(|r|r.bytes())),r["queue"]);assert_eq!((env.draws.len(),env.crt,env.blast,env.spark,env.flag),(n("draws")as usize,n("crt")as usize,n("blast")as usize,n("spark")as usize,n("flag")as u8));for v in[s as u32,tick as u32,n("before")as u32,n("constructHash")as u32,after,env.draws.len()as u32,env.crt as u32,env.blast as u32,env.spark as u32,4,u32::from(env.flag)]{mix(&mut all,v);}for p in 0..4{mix(&mut all,0x595d06+p*900);mix(&mut all,damage as u32);}count+=1;}assert_eq!(count,96);assert_eq!(all,1615055178);}
